import html, json
from pathlib import Path

def build(out: Path, results, alerts, report):
    triage=json.loads((out/'triage.json').read_text())
    payload=json.dumps({'results':results,'alerts':alerts,'triage':triage},ensure_ascii=True).replace('<','\\u003c')
    template=r'''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Malware Analysis Lab</title>
<style>
:root{color-scheme:dark;--bg:#080e16;--panel:#121d29;--line:#293848;--text:#e9f0f5;--muted:#9cabba;--accent:#74ebc3;--gold:#ffc56b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px system-ui}main{max-width:1200px;margin:auto;padding:35px 24px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:25px}.brand{font-size:12px;letter-spacing:3px;color:var(--accent)}.tag{border:1px solid var(--line);border-radius:30px;padding:9px 14px;color:var(--muted)}h1{font-size:clamp(35px,6vw,67px);line-height:1.02;margin:38px 0 18px;letter-spacing:-2px}h1 span{color:var(--accent)}.intro{max-width:700px;color:var(--muted);font-size:18px;line-height:1.6}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:30px 0}.card,.panel{background:var(--panel);border:1px solid var(--line);border-radius:15px;padding:23px}.card strong{display:block;font-size:30px;color:var(--accent)}.card small{color:var(--muted)}.row{display:grid;grid-template-columns:1.3fr 1fr;gap:18px;margin:18px 0}.panel h2{margin-top:0;font-size:19px}button{background:transparent;color:var(--muted);border:1px solid var(--line);border-radius:8px;padding:10px 15px;cursor:pointer}button.active{background:var(--accent);color:#08130e;border-color:var(--accent)}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px 8px;border-bottom:1px solid var(--line);font-size:13px;vertical-align:top}.pill{color:var(--gold)}pre{white-space:pre-wrap;overflow-wrap:anywhere;color:var(--muted);font:13px ui-monospace;line-height:1.7}.topology{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.node{border:1px solid var(--accent);border-radius:10px;padding:18px}.arrow{color:var(--accent)}details{margin:15px 0}summary{cursor:pointer;color:var(--accent)}a{color:var(--accent)}.foot{color:var(--muted);font-size:12px;line-height:1.6;padding:20px 0}@media(max-width:750px){.grid{grid-template-columns:1fr 1fr}.row{grid-template-columns:1fr}header{align-items:start;gap:10px}}
</style><main><header><div class="brand">SECURITY RESEARCH LAB</div><div class="tag">Preuves réelles · RUN_ID</div></header>
<h1>Malware Analysis Lab<br><span>AI-assisted Detection.</span></h1><p class="intro">Une investigation reproductible : observer le trafic, corréler les événements et mesurer les protections. MCP donne à l’IA un accès borné aux outils et aux preuves.</p>
<div class="grid"><div class="card"><strong>2</strong><small>Conteneurs / réseau interne</small></div><div class="card"><strong>512 Mo</strong><small>Plafond RAM des conteneurs</small></div><div class="card"><strong id="checks"></strong><small>Contrôles fonctionnels PASS</small></div><div class="card"><strong id="alerts"></strong><small>Alertes corrélées</small></div></div>
<div class="panel"><h2>Le chemin des preuves</h2><div class="topology"><div class="node">Client IA → MCP</div><span class="arrow">→</span><div class="node">Station · capture / triage</div><span class="arrow">⇄</span><div class="node">Cible · HTTP / SQLite</div><span class="arrow">→</span><div class="node">PCAP + journaux</div></div><p class="foot">Le modèle fonctionne dans le client MCP. Aucun modèle lourd dans les conteneurs. Les scénarios sont synthétiques et le triage n’exécute jamais l’échantillon.</p></div>
<div class="row"><section class="panel"><h2>Investigation réseau</h2><div><button id="vulnerable" class="active" onclick="selectPhase('vulnerable')">Avant protection</button> <button id="hardened" onclick="selectPhase('hardened')">Après protection</button></div><table><thead><tr><th>Signal</th><th>Observation vérifiée</th></tr></thead><tbody id="observations"></tbody></table><div id="detections"></div></section><section class="panel"><h2>Triage statique · fixture inoffensif</h2><p class="pill">Verdict : indéterminé / fichier non exécuté</p><pre id="triage"></pre><details><summary>Chaînes extraites : données non fiables</summary><pre id="strings"></pre></details></section></div>
<section class="panel"><h2>Contrôles et artefacts</h2><table id="tests"></table><p><a href="vulnerable.pcap">PCAP avant</a> · <a href="hardened.pcap">PCAP après</a> · <a href="alerts.json">Alertes JSON</a> · <a href="rapport.md">Rapport</a> · <a href="SHA256SUMS">Empreintes</a></p><details><summary>Rapport technique complet</summary><pre>REPORT</pre></details></section><p class="foot">Deux conteneurs partagent le noyau WSL2 : adaptation à faire accepter si deux VM sont obligatoires. Détection offline de démonstration. Une signature seule ne prouve pas une compromission. L’intégration MCP est distincte de la validation d’un modèle IA.</p></main>
<script id="data" type="application/json">PAYLOAD</script><script>
const data=JSON.parse(document.getElementById('data').textContent);const el=id=>document.getElementById(id);el('checks').textContent=Object.values(data.results.checks).filter(Boolean).length;el('alerts').textContent=data.alerts.length;
function row(table,a,b){const tr=document.createElement('tr');for(const s of [a,b]){const td=document.createElement('td');td.textContent=s;tr.appendChild(td)}table.appendChild(tr)}
for(const [k,v] of Object.entries(data.results.checks))row(el('tests'),k,v?'PASS':'FAIL');
const t=data.triage;el('triage').textContent='SHA256\n'+t.sha256+'\n\nTaille : '+t.bytes+' octets\nEntropie : '+t.entropy+' bits/octet\nType : '+(t.file_description||t.type_hint)+'\n\nYARA : '+(t.yara_matches||[]).join(', ')+'\n\nIndicateurs :\n'+t.network_indicators_untrusted.join('\n');el('strings').textContent=t.strings_untrusted.join('\n');
function selectPhase(mode){for(const m of ['vulnerable','hardened'])el(m).classList.toggle('active',m===mode);const r=data.results[mode];el('observations').replaceChildren();row(el('observations'),'Connexion incorrecte',r.failed_login_statuses.join(' → '));row(el('observations'),'Bon mot de passe après rafale','HTTP '+r.correct_login_after_attempts[0]);row(el('observations'),'Réponse à l’injection',JSON.stringify(r.sql_injection[1]));el('detections').replaceChildren();for(const a of data.alerts.filter(x=>x.mode===mode)){const p=document.createElement('p');p.className='foot';p.textContent=a.rule+' · '+a.evidence+(a.frame?' · trame '+a.frame:'')+(a.distinct_ports?' · '+a.distinct_ports+' ports':'');el('detections').appendChild(p)}}selectPhase(location.hash==='#hardened'?'hardened':'vulnerable');
</script></html>'''
    return template.replace('RUN_ID',html.escape(out.name)).replace('REPORT',html.escape(report)).replace('PAYLOAD',payload)
